  private static sameStringArray(first: readonly string[], second: readonly string[]): boolean {
    if (first.length !== second.length) {
      return false;
    }
    let index = 0;
    while (index < first.length) {
      if (first[index]! !== second[index]!) {
        return false;
      }
      index += 1;
    }
    return true;
  }

